#[derive(Debug, Default, Clone, clap::Args)]
pub struct WorkflowOptions {
    /// Save editable release title, body, changelog, and review as JSON
    #[arg(long, conflicts_with = "github_release")]
    pub draft: Option<PathBuf>,
    /// Write a Markdown coverage report with sources and omission reasons
    #[arg(long)]
    pub review_report: Option<PathBuf>,
    /// Write an upgrade guide with affected users and before/after examples
    #[arg(long)]
    pub migration_guide: Option<PathBuf>,
    /// Generate notes for a package configured in communique.toml
    #[arg(long)]
    pub package: Option<String>,
    /// Limit changes to repository-relative paths (repeatable)
    #[arg(long = "path")]
    pub paths: Vec<String>,
    /// Only consider baseline tags matching this git glob
    #[arg(long)]
    pub tag_pattern: Option<String>,
    /// Baseline channel: stable excludes prereleases; all includes them
    #[arg(long, value_enum)]
    pub channel: Option<Channel>,
    /// Changelog destination relative to the repository root
    #[arg(long)]
    pub changelog_path: Option<PathBuf>,
    /// Replace only the communique-marked section of a GitHub release
    #[arg(long)]
    pub preserve_sections: bool,
}

#[derive(Debug, Clone, Copy, Default, Deserialize, clap::ValueEnum)]
#[serde(rename_all = "lowercase")]
pub enum Channel {
    Stable,
    #[default]
    All,
}

#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Package {
    #[serde(default)]
    pub paths: Vec<String>,
    pub tag_pattern: Option<String>,
    pub channel: Option<Channel>,
    pub changelog_path: Option<PathBuf>,
}

#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Rules {
    #[serde(default)]
    pub include_labels: Vec<String>,
    #[serde(default)]
    pub exclude_labels: Vec<String>,
    #[serde(default)]
    pub categories: BTreeMap<String, String>,
}

impl WorkflowOptions {
    pub fn resolve(&mut self, config: &crate::config::Config) -> miette::Result<()> {
        if let Some(name) = &self.package {
            let package = config.packages.get(name)
                .ok_or_else(|| miette::miette!("Unknown package '{name}' in communique.toml"))?;
            if self.paths.is_empty() { self.paths = package.paths.clone(); }
            self.tag_pattern = self.tag_pattern.take().or(package.tag_pattern.clone());
            self.channel = self.channel.or(package.channel);
            self.changelog_path = self.changelog_path.take().or(package.changelog_path.clone());
        }
        for path in self.paths.iter().map(Path::new).chain(self.changelog_path.iter().map(PathBuf::as_path)) {
            if path.as_os_str().is_empty() || path.components().any(|c| !matches!(c, std::path::Component::Normal(_) | std::path::Component::CurDir)) {
                return Err(miette::miette!("Paths must be relative to the repository and cannot contain '..': {}", path.display()));
            }
        }
        Ok(())
    }
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct Review {
    pub coverage: Vec<Coverage>,
    pub migration_guide: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Coverage {
    pub commit: String,
    pub status: String,
    pub reason: String,
}

impl Review {
    pub fn from_submission(input: &serde_json::Value) -> Self {
        Self {
            coverage: serde_json::from_value(input["coverage"].clone()).unwrap_or_default(),
            migration_guide: input["migration_guide"].as_str().unwrap_or_default().to_string(),
        }
    }

    /// Keep only known commits, fill gaps explicitly, and preserve enforced exclusions.
    pub fn reconcile(&mut self, log: &str, excluded: Vec<Coverage>) {
        let mut entries = Vec::new();
        for line in log.lines() {
            let sha = line.split_whitespace().next().unwrap_or_default();
            let matches: Vec<_> = self.coverage.iter().filter(|c| c.commit == sha).collect();
            let entry = if matches.len() == 1 && ["included", "omitted", "uncertain"].contains(&matches[0].status.as_str()) && !matches[0].reason.trim().is_empty() {
                matches[0].clone()
            } else {
                Coverage { commit: sha.into(), status: "uncertain".into(), reason: "The model did not provide a valid, unique assessment; review this change manually.".into() }
            };
            entries.push(entry);
        }
        entries.extend(excluded);
        self.coverage = entries;
    }

    pub fn markdown(&self, repo: &str, from: &str, to: &str) -> String {
        let mut result = format!("# Release coverage\n\nRange: `{from}..{to}`\n\nAssessments are model-generated, except explicit label exclusions. Uncertain entries require manual review.\n");
        for entry in &self.coverage {
            result.push_str(&format!("\n- **{}** [{}](https://github.com/{repo}/commit/{}): {}\n", entry.status, entry.commit, entry.commit, entry.reason));
        }
        result
    }
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Draft {
    pub schema_version: u32,
    pub repo: String,
    pub tag: String,
    pub previous_ref: String,
    pub target_commit: String,
    pub release_title: String,
    pub release_body: String,
    pub changelog: String,
    pub preserve_sections: bool,
    pub review: Review,
}

impl Draft {
    pub fn new(repo: &str, tag: &str, previous_ref: &str, target_commit: &str, notes: &ParsedOutput, preserve_sections: bool) -> Self {
        Self { schema_version: 1, repo: repo.into(), tag: tag.into(), previous_ref: previous_ref.into(), target_commit: target_commit.into(), release_title: notes.release_title.clone(), release_body: notes.release_body.clone(), changelog: notes.changelog.clone(), preserve_sections, review: notes.review.clone() }
    }
    pub fn write(&self, path: &Path) -> miette::Result<()> {
        std::fs::write(path, format!("{}\n", serde_json::to_string_pretty(self).into_diagnostic()?)).into_diagnostic()
    }
    fn validate(&self) -> miette::Result<()> {
        if self.schema_version != 1 { return Err(miette::miette!("Unsupported draft schema version {}", self.schema_version)); }
        if self.tag == "HEAD" || self.tag.trim().is_empty() { return Err(miette::miette!("Publishing requires a release tag, not HEAD")); }
        if self.release_title.trim().is_empty() || self.release_body.trim().is_empty() { return Err(miette::miette!("Draft title and body cannot be empty")); }
        let parts: Vec<_> = self.repo.split('/').collect();
        if parts.len() != 2 || parts.iter().any(|p| p.is_empty() || !p.chars().all(|c| c.is_ascii_alphanumeric() || "-_.".contains(c))) { return Err(miette::miette!("Draft repo must be owner/repo")); }
        Ok(())
    }
}

pub const START: &str = "<!-- communique:start -->";
pub const END: &str = "<!-- communique:end -->";

pub fn merge_body(existing: &str, generated: &str) -> miette::Result<String> {
    if generated.contains(START) || generated.contains(END) { return Err(miette::miette!("Generated body must not contain communique section markers")); }
    let starts: Vec<_> = existing.match_indices(START).collect();
    let ends: Vec<_> = existing.match_indices(END).collect();
    match (starts.as_slice(), ends.as_slice()) {
        ([], []) => Ok(format!("{}{}{}\n{}\n{}", existing, if existing.is_empty() { "" } else { "\n\n" }, START, generated, END)),
        ([(start, _)], [(end, _)]) if start < end => Ok(format!("{}\n{}\n{}", &existing[..start + START.len()], generated, &existing[*end..])),
        _ => Err(miette::miette!("Release must contain either no communique markers or exactly one ordered start/end pair")),
    }
}

pub async fn publish_draft(path: &Path, dry_run: bool) -> miette::Result<()> {
    let draft: Draft = serde_json::from_str(&std::fs::read_to_string(path).into_diagnostic()?).into_diagnostic()?;
    draft.validate()?;
    if dry_run && !draft.preserve_sections {
        println!("# {}\n\n{}", draft.release_title, draft.release_body);
        return Ok(());
    }
    let token = std::env::var("GITHUB_TOKEN").into_diagnostic().map_err(|_| miette::miette!("GITHUB_TOKEN is required to read or update the release"))?;
    let gh = GitHubClient::new(token, &draft.repo)?;
    let release = gh.get_release_by_tag(&draft.tag).await?.ok_or_else(|| miette::miette!("No GitHub release found for {}", draft.tag))?;
    let body = if draft.preserve_sections { merge_body(release.body.as_deref().unwrap_or_default(), &draft.release_body)? } else { draft.release_body };
    if dry_run { println!("# {}\n\n{}", draft.release_title, body); }
    else {
        gh.update_release(release.id, if draft.preserve_sections { None } else { Some(&draft.release_title) }, Some(&body)).await?;
        eprintln!("Updated {}/{}", draft.repo, draft.tag);
    }
    Ok(())
}
