async fn apply_rules(ctx: &Context, log: &str) -> miette::Result<(String, Vec<crate::workflow::Coverage>, String)> {
    let rules = &ctx.rules;
    let active = !rules.include_labels.is_empty() || !rules.exclude_labels.is_empty() || !rules.categories.is_empty();
    if !active { return Ok((log.into(), vec![], String::new())); }
    let gh = ctx.github_client.as_ref().ok_or_else(|| miette::miette!("GITHUB_TOKEN is required to apply configured label rules"))?;
    let mut prs = std::collections::BTreeMap::new();
    for number in git::extract_pr_numbers(log) {
        if let std::collections::btree_map::Entry::Vacant(entry) = prs.entry(number) {
            entry.insert(gh.get_pr(number).await?);
        }
    }
    let mut kept = Vec::new();
    let mut excluded = Vec::new();
    let mut guidance = String::new();
    for line in log.lines() {
        let numbers = git::extract_pr_numbers(line);
        let labels: Vec<_> = numbers.iter().filter_map(|n| prs.get(n)).flat_map(|pr| pr.labels.iter().map(|l| l.name.as_str())).collect();
        let include = rules.include_labels.iter().any(|l| labels.contains(&l.as_str()));
        let skip = rules.exclude_labels.iter().find(|l| labels.contains(&l.as_str()));
        let sha = line.split_whitespace().next().unwrap_or_default();
        if !include && let Some(label) = skip {
            excluded.push(crate::workflow::Coverage { commit: sha.into(), status: "omitted".into(), reason: format!("Excluded by configured PR label '{label}'.") });
            guidance.push_str(&format!("Do not include commit {sha}: excluded by label {label}.\n"));
            continue;
        }
        kept.push(line);
        if include { guidance.push_str(&format!("Commit {sha} MUST appear in the notes (include-label override).\n")); }
        for (label, category) in &rules.categories {
            if labels.contains(&label.as_str()) { guidance.push_str(&format!("Categorize commit {sha} under {category} (label {label}).\n")); }
        }
    }
    Ok((kept.join("\n"), excluded, guidance))
}
